INSERT INTO _fleet_sync_epoch_history(database,epoch,holder,granted_at,ended_epoch,ended_sequence) VALUES(?1,?2,json_extract(?3,'$.holder'),json_extract(?3,'$.granted_at'),NULLIF(?3 -> '$.ended_at.epoch','null'),NULLIF(?3 -> '$.ended_at.sequence','null')) ON CONFLICT(database,epoch) DO UPDATE SET holder=excluded.holder,granted_at=excluded.granted_at,ended_epoch=excluded.ended_epoch,ended_sequence=excluded.ended_sequence,updated_at=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER))
